/** Items, and whether each needs you (domain/rules.py needs_you), by its number. */
export interface NeedsCase {
  items: Item[]
  needs: Record<string, boolean>
}

/** A message, and whether it is the user's own words (user_word). */
export interface UserWordCase {
  by: string
  kind: Kind
  src: string | null
  user: boolean
}

/** Items, and the order agents take them (queue_order). */
export interface QueueCase {
  items: Item[]
  order: number[]
}

/** A project, the inputs whose voice notes are still being worked out, and the item /next hands out next. */
export interface NextCase {
  items: Item[]
  inputs: Input[]
  held: string[]
  next: number | null
}

